using System;

namespace StdbModule;

public static partial class GermanQuotes
{
    public static class JohannWolfgangvonGoethe
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der edle Mensch // Sei hülfreich und gut! // Unermüdet schaff er // Das Nützliche, Rechte, // Sei uns ein Vorbild // Jener geahneten Wesen!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Edel sei der Mensch, // Hülfreich und gut! // Denn das allein // Unterscheidet ihn // Von allen Wesen, // Die wir kennen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Nach ewigen, ehrnen, // Großen Gesetzen // Müssen wir alle // Unseres Daseins // Kreise vollenden.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Nur allein der Mensch // Vermag das Unmögliche: // Er unterscheidet, // Wählet und richtet; // Er kann dem Augenblick // Dauer verleihen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Hier sitz’ ich, forme Menschen // Nach meinem Bilde, // Ein Geschlecht, das mir gleich sey, // Zu leiden, zu weinen, // Zu genießen und zu freuen sich, // Und dein nicht zu achten, // Wie ich!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Denn das Leben ist die Liebe // Und des Lebens Leben Geist", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Dichten ist ein Übermut!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Es gibt nur drei echte Naturformen der Poesie: die klar erzählende, die enthusiastisch aufgeregte und die persönlich handelnde: Epos, Lyrik und Drama. Diese drei Dichtweisen können zusammen oder abgesondert wirken.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein großer Fehler: daß man sich mehr dünkt, als man ist, und sich weniger schätzt, als man wert ist.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Für Sorgen sorgt das liebe Leben // Und Sorgenbrecher sind die Reben.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Getretner Quark // Wird breit, nicht stark.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Gottes ist der Orient! // Gottes ist der Occident! Nord- und südliches Gelände // Ruht im Frieden seiner Hände!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Jugend ist Trunkenheit ohne Wein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Laß dich nur in keiner Zeit // Zum Widerspruch verleiten, // Weise fallen in Unwissenheit, // Wenn sie mit Unwissenden streiten.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Närrisch, dass jeder in seinem Falle // Seine besondere Meinung preist! // Wenn Islam »Gott ergeben« heißt, // In Islam leben und sterben wir alle.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Nur klugtätige Menschen, die ihre Kräfte kennen und sie mit Maß und Gescheitigkeit benutzen, werden es im Weltwesen weit bringen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Sagt es niemand, nur den Weisen // Weil die Menge gleich verhöhnet.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Sich im Respekt zu erhalten // Muss man recht borstig sein. // Alles jagt man mit Falken, // Nur nicht das wilde Schwein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer nicht von dreitausend Jahren // Sich weiß Rechenschaft zu geben, // Bleib im Dunkeln unerfahren, // Mag von Tag zu Tage leben.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer schweigt, hat wenig zu sorgen; // Der Mensch bleibt unter der Zunge verborgen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Will der Neid sich doch zerreißen, // Lass ihn seinen Hunger speisen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Amerika, du hast es besser // Als unser Continent, das alte, // Hast keine verfallene Schlösser // Und keine Basalte.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Das Leben wohnt in jedem Sterne: // Er wandelt mit den andern gerne // Die selbsterwählte, reine Bahn, // Im innern Erdenball pulsieren // Die Kräfte, die zur Nacht uns führen // Und wieder zu dem Tag heran.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Den deutschen Mannen gereicht´s zum Ruhm, // Dass sie gehasst das Christentum, // Bis Herrn Carolus' leidigem Degen // Die edlen Sachsen unterlegen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der Alte schlummert wie das Kind, // Und wie wir eben Menschen sind, // Wir schlafen sämtlich auf Vulkanen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Axt erklingt, da blinkt schon jedes Beil, // Die Eiche fällt, und jeder holzt sein Teil.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Glaubt nicht, dass ich fasele, dass ich dichte; // Seht hin und findet mir andre Gestalt! // Es ist die ganze Kirchengeschichte // Mischmasch von Irrtum und von Gewalt.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ihr schmähet meine Dichtung, // Was habt ihr denn getan? // Wahrhaftig, die Vernichtung, // Verneinend fängt sie an, // Doch ihren scharfen Besen // Strengt sie vergebens an: // Ihr seid gar nicht gewesen! // Wo träfe sie euch an?", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Im Auslegen seid frisch und munter! Legt ihr's nicht aus, so legt was unter.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Lasst euch nur von Pfaffen sagen, // Was die Kreuzigung eingetragen! // Niemand kommt zum höchsten Flor // Von Kranz und Orden, // Wenn einer nicht zuvor // Derb gedroschen worden.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Seit sechzig Jahren seh ich gröblich irren // Und irre so derb mit drein, // Da Labyrinthe nun das Labyrinth verwirren, // Wo soll euch Ariadne sein?", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Vom Vater hab ich die Statur, // Des Lebens ernstes Führen, // Von Mütterchen die Frohnatur // Und Lust zu fabulieren.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wär nicht das Auge sonnenhaft, // die Sonne könnt es nie erblicken. // Läg nicht in uns des Gottes eigne Kraft, // Wie könnt uns Göttliches entzücken?", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Was auch als Wahrheit oder Fabel // In tausend Büchern dir erscheint, // Das alles ist ein Turm zu Babel, // Wenn es die Liebe nicht vereint.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Was ich nicht loben kann, // Davon sprech ich nicht.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Was lassen sie denn übrig zuletzt, // Jene unbescheidnen Besen? // Behauptet doch Heute steif und fest, // Gestern sei nicht gewesen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer mit dem Leben spielt, kommt nie zurecht; // wer sich nicht selbst befiehlt, bleibt immer Knecht.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer Wissenschaft und Kunst besitzt, hat auch Religion; wer jene beiden nicht besitzt, der habe Religion.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wie einer ist, so ist sein Gott, // Darum ward Gott so oft zu Spott.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Armut, Keuschheit und Gehorsam, – drei Gelübde, deren jedes, einzeln betrachtet, der Natur das unausstehlichste scheint, so unerträglich sind sie alle.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Auch der Aufschub hat seine Freuden.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Das ist Weibergunst! Erst brütet sie mit Mutterwärme unsere liebsten Hoffnungen an, dann gleich einer unbeständigen Henne verläßt sie das Nest und übergibt ihre schon keimende Nachkommenschaft dem Tod und der Verwesung.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der Großmütige gleicht einem Mann, der mit seinem Abendbrot Fische fütterte, aus Unachtsamkeit in den Teich fiel und ersoff.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Jagd ist doch immer was, und eine Art von Krieg.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Menge schätzt nur den Widerschein des Verdienstes.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Welt ist ein Gefängnis.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Es ist eine Wollust, einen großen Mann zu sehn.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Glückliches Kind! Das kein Übel kennt, als wenn die Suppe lang ausbleibt.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Glück macht Mut", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wenn Euer Gewissen rein ist, so seid Ihr Freiheit.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wollte, Gott hätte mich zum Gärtner oder zum Laboranten gemacht! Ich könnte glücklich sein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wo viel Licht ist, ist starker Schatten.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Da fing mein Leben an, als ich dich liebte.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der Zweifel ist's, der Gutes böse macht.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Vorsicht stellt der List sich klug entgegen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Du sprichst ein großes Wort gelassen aus.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Man spricht vergebens viel, um zu versagen; Der andre hört von allem nur das Nein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Um Guts zu tun, braucht's keiner Überlegung.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Unendlich ist das Werk, das zu vollbringen // Die Seele dringt.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Zwischen uns sei Wahrheit.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Aber die Sonne duldet kein Weißes, // Überall regt sich Bildung und Streben, // Alles will sie mit Farben beleben; // Doch an Blumen fehlts im Revier, // Sie nimmt geputzte Menschen dafür.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ach neige, // Du Schmerzenreiche, // Dein Antlitz gnädig meiner Not!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Allein der Vortrag macht des Redners Glück.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Allwissend bin ich nicht; doch viel ist mir bewusst.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Bedenkt, Ihr habet weiches Holz zu spalten.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Bescheidne Wahrheit sprech ich dir. // Wenn sich der Mensch, die kleine Narrenwelt, // Gewöhnlich für ein Ganzes hält.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Besonders lernt die Weiber führen; // Es ist ihr ewig Weh und Ach // So tausendfach // Aus e i n e m Punkte zu kurieren.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Blut ist ein ganz besondrer Saft.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Das also war des Pudels Kern!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Das Alter macht nicht kindisch, wie man spricht, // Es findet uns nur noch als wahre Kinder.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Dass ich erkenne, was die Welt // Im Innersten zusammenhält.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Das Wunder ist des Glaubens liebstes Kind", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Dem Hunde, wenn er gut gezogen, // Wird selbst ein weiser Mann gewogen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Dem Volke hier wird jeder Tag ein Fest. // Mit wenig Witz und viel Behagen // dreht jeder sich im engen Zirkeltanz, // Wie junge Katzen mit dem Schwanz.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Den Teufel spürt das Völkchen nie, // und wenn er sie beim Kragen hätte.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Denn eben wo Begriffe fehlen, // Da stellt ein Wort zur rechten Zeit sich ein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Denn was man schwarz auf weiß besitzt, // Kann man getrost nach Hause tragen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der Äpfelchen begehrt Ihr sehr, // Und schon vom Paradiese her. // Von Freuden fühl ich mich bewegt, // Dass auch mein Garten solche trägt.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der ganze Strudel strebt nach oben; // Du glaubst zu schieben, und du wirst geschoben.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der letzte Trunk sei nun, mit ganzer Seele, // Als festlich hoher Gruß, dem Morgen zugebracht!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der Menschheit ganzer Jammer faßt mich an.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der saubern Herren Pfuscherei // Ist, merk ich, schon bei Euch Maxime.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der Worte sind genug gewechselt, // Laßt mich auch endlich Taten sehn; // Indes ihr Komplimente drechselt, // Kann etwas Nützliches geschehn.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Des Menschen Tätigkeit kann allzuleicht erschlaffen, // Er liebt sich bald die unbedingte Ruh; // Drum geb ich gern ihm den Gesellen zu, // Der reizt und wirkt und muß als Teufel schaffen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Botschaft hör ich wohl, allein mir fehlt der Glaube.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Kirche hat einen guten Magen, // Hat ganze Länder aufgefressen // Und doch noch nie sich übergessen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Kunst ist lang! // Und kurz ist unser Leben.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Masse könnt ihr nur durch Masse zwingen, // Ein jeder sucht sich endlich selbst was aus.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Pfosten sind, die Bretter aufgeschlagen, // Und jedermann erwartet sich ein Fest.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die schlechteste Gesellschaft läßt dich fühlen, // Dass du ein Mensch mit Menschen bist.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Träne quillt, die Erde hat mich wieder.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Zeiten der Vergangenheit // Sind uns ein Buch mit sieben Siegeln.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Doch werdet ihr nie Herz zu Herzen schaffen, // Wenn es Euch nicht von Herzen geht.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Du gleichst dem Geist, den Du begreifst.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Du kannst! So wolle nur!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein echter deutscher Mann mag keinen Franzen (Franzosen) leiden, // Doch ihre Weine trinkt er gern.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein garstig Lied! Pfui! ein politisch Lied!// Ein leidig Lied!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Eine Ratt' im Kellernest,// [...] Die Köchin hatt' ihr Gift gestellt; Da ward's so eng ihr in der Welt,// Als hätte sie Lieb' im Leibe.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein guter Mensch in seinem dunklen Drange // Ist sich des rechten Weges wohl bewusst.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein jeder lernt nur, was er lernen kann; // Doch der den Augenblick ergreift, // Das ist der rechte Mann.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein Kerl, der spekuliert (hier: grübelt, sich in Gedanken verspinnt), // Ist wie ein Tier, auf dürrer Heide // Von einem bösen Geist im Kreis herumgeführt, // Und ringsumher liegt schöne grüne Weide.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein Mann, der recht zu wirken denkt, // Muss auf das beste Werkzeug halten.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ich bin von je der Ordnung Freund gewesen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ich hab es öfters rühmen hören, // Ein Komödiant könnt einen Pfarrer lehren.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ihr habt das Recht, gesittet pfui zu sagen. // Man darf das nicht vor keuschen Ohren nennen, // Was keusche Herzen nicht entbehren können.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ihr Mann ist tot und lässt Sie grüßen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ihr naht euch wieder, schwankende Gestalten.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ihr wisst, auf unsern deutschen Bühnen // Probiert ein jeder, was er mag.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Im Anfang war die Tat!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "In jedem Kleide werd ich wohl die Pein // Des engen Erdelebens fühlen. // Ich bin zu alt, um nur zu spielen, // Zu jung, um ohne Wunsch zu sein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Mein Leipzig lob ich mir! // Es ist ein klein Paris und bildet seine Leute.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Mein schönes Fräulein, darf ich wagen, // Meinen Arm und Geleit Ihr anzutragen?", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Mir wird von alledem so dumm, // als ging mir ein Mühlrad im Kopf herum.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Mit Euch, Herr Doktor, zu spazieren // Ist ehrenvoll und ist Gewinn.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Mit Frauen soll man sich nie unterstehn zu scherzen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Mit Worten lässt sich trefflich streiten.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Nach einem selbstgesteckten Ziel // Mit holdem Irren hinzuschweifen, // Das, alte Herrn, ist eure Pflicht.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Nun sag, wie hast du's mit der Religion?", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Nur rastlos betätigt sich der Mann.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "O glücklich, wer noch hoffen kann, // Aus diesem Meer des Irrtums aufzutauchen! // Was man nicht weiß, das eben brauchte man, // Und was man weiß, kann man nicht brauchen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "O sprich mir nicht von jener bunten Menge, // Bei deren Anblick uns der Geist entflieht.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "O wär ich nie geboren!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Sie ist die erste nicht!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Sie sitzen schon, mit hohen Augenbraunen // Gelassen da und möchten gern erstaunen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "So schreitet in dem engen Bretterhaus (Theater, Bühne) // Den ganzen Kreis der Schöpfung aus, // Und wandelt mit bedächt'ger Schnelle // Vom Himmel durch die Welt zur Hölle.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Sobald du dir vertraust, sobald weißt du zu leben.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Sucht nur die Menschen zu verwirren, // Sie zu befriedigen ist schwer.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Sünde und Schande // Bleibt nicht verborgen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Uns ist ganz kannibalisch wohl, // Als wie fünfhundert Säuen!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Unsre Taten selbst, so gut als unsre Leiden, // Sie hemmen unsres Lebens Gang.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Vom Eise befreit sind Strom und Bäche // Durch des Frühlings holden belebenden Blick.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Von Zeit zu Zeit seh ich den Alten gern // Und hüte mich, mit ihm zu brechen. // Es ist gar hübsch von einem großen Herrn, // so menschlich mit dem Teufel selbst zu sprechen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Was du ererbt von deinen Vätern hast, // erwirb es, um es zu besitzen. // Was man nicht nützt, ist eine schwere Last; // Nur was der Augenblick erschafft, das kann er nützen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Was glänzt, ist für den Augenblick geboren; // Das Echte bleibt der Nachwelt unverloren.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Was ihr den Geist der Zeiten heißt, // Das ist im Grund der Herren eigner Geist, // In dem die Zeiten sich bespiegeln.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Was willst du dich das Stroh zu dreschen plagen?", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Welch Schauspiel! aber ach! ein Schauspiel nur!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wenn ich sechs Hengste zahlen kann, // Sind ihre Kräfte nicht die meine? // Ich renne zu und bin ein rechter Mann, // Als hätt ich vierundzwanzig Beine.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer darf das Kind beim rechten Namen nennen? // Die wenigen, die was davon erkannt, // Die töricht gnug ihr volles Herz nicht wahrten, // Dem Pöbel ihr Gefühl, ihr Schauen offenbarten, // Hat man von je gekreuzigt und verbrannt.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer fertig ist, dem ist nichts recht zu machen, // Ein Werdender wird immer dankbar sein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Werd ich zum Augenblicke sagen: // Verweile doch! Du bist so schön! // Dann magst du mich in Fesseln schlagen, // dann will ich gern zugrunde gehn!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer sich behaglich mitzuteilen weiß, // den wird des Volkes Laune nicht erbittern.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer vieles bringt, wird manchem etwas bringen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wie alles sich zum Ganzen webt, // Eins in dem andern wirkt und lebt!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wie glücklich würde sich der Affe schätzen, // Könnt er nur auch ins Lotto setzen!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wo fass ich dich, unendliche Natur? // Euch Brüste, wo? Ihr Quellen alles Lebens.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Zwar weiß ich viel, doch möcht ich alles wissen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Zwei Seelen wohnen, ach! in meiner Brust, // Die eine will sich von der andern trennen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Alles Vergängliche // Ist nur ein Gleichnis // Das Unzulängliche, // Hier wirds Ereignis; // Das Unbeschreibliche, // Hier ist es getan; // Das Ewig-Weibliche // Zieht uns hinan.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Alt ist das Wort, doch bleibet hoch und wahr der Sinn, // Dass Scham und Schönheit nie zusammen, Hand in Hand, // Den Weg verfolgen über der Erde grünen Pfad.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Auch ein gelehrter Mann // Studiert so fort, weil er nicht anders kann. // So baut man sich ein mäßig Kartenhaus, // Der größte Geist baut's doch nicht völlig aus.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Auf strenges Ordnen, raschen Fleiß // Erfolgt der allerschönste Preis; // Dass sich das Werk vollende, // Genügt ein Geist für tausend Hände.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Bewundert viel und viel gescholten, Helena", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Bin männlichen Geschlechts, der Geiz!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Das ist der Weisheit letzter Schluss: // Nur der verdient sich Freiheit wie das Leben, // Der täglich sie erobern muss.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Das Schaudern ist der Menschheit bestes Teil.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Dem Tüchtigen ist diese Welt nicht stumm.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Den lieb ich, der Unmögliches begehrt.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Denn wer den Schatz, das Schöne, heben will, // Bedarf der höchsten Kunst: Magie der Weisen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Denn wo Gespenster Platz genommen, // Ist auch der Philosoph willkommen. // Damit man seiner Kunst und Gunst sich freue, // Erschafft er gleich ein Dutzend neue.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Der Rost macht erst die Münze wert", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Des Lebens Pulse schlagen frisch lebendig, // Ätherische Dämmerung milde zu begrüßen; // Du, Erde, warst auch diese Nacht beständig // Und atmest neu erquickt zu meinen Füßen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Sorge, sie schleicht sich durchs Schlüsselloch ein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Tat ist alles, nichts der Ruhm.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Welle beugt sich jedem Winde gern.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Dieser Erdenkreis // gewährt noch Raum zu großen Taten.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Einbläsereien sind des Teufels Redekunst.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein großer Aufwand, schmählich! ist vertan.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein jeder ist an seinem Platz unsterblich.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Gehorche willig der Gewalt! // Und bist du kühn und hältst du Stich (stand), // So wage Haus und Hof und – dich.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Hoch ist der Doppelgewinn zu schätzen: // Barmherzig sein, und sich zugleich ergetzen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ihr bleibt bei meinem Worte kalt, // Euch guten Kindern lass ich's gehen; // Bedenkt: der Teufel, der ist alt, // So werdet alt, ihn zu verstehen!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ihr glücklichen Augen, // Was je ihr gesehn, // Es sei wie es wolle, // Es war doch so schön!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Im Deutschen lügt man, wenn man höflich ist.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Krieg, Handel und Piraterie, // Dreieinig sind sie, nicht zu trennen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Man säe nur, man erntet mit der Zeit.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Mein Fußtritt, Kind! hat Größres zu bedeuten. // Zu Gleichem Gleiches, was auch einer litt; // Fuß heilet Fuß, so ist's mit allen Gliedern.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Rechnung für Rechnung ist berichtigt, // Die Wucherklauen sind beschwichtigt, // Los bin ich solcher Pein (Höllenpein); // Im Himmel kann's nicht heitrer sein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Rosen, ihr blendenden, // Balsam versendenden! // Flatternde, schwebende, // Heimlich belebende, // Zweiglein beflügelte, // Knospen entsiegelte, // Eilet zu blühn!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Sie streiten sich, [...] um Freiheitsrechte; // Genau besehn, sind's Knechte gegen Knechte.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Solch ein Gewimmel möcht ich sehn, // Auf freiem Grund mit freiem Volke stehn.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Soll zwischen uns kein fernster Zwist sich regen, Ich liebe mir den Zauberer zum Kollegen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Stünd ich, Natur, vor dir ein Mann allein, // Da wär's der Mühe wert, ein Mensch zu sein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Über Rosen lässt sich dichten, // In die Äpfel muss man beißen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Uns bleibt ein Erdenrest // Zu tragen peinlich, // Und wär er von Asbest (unvergänglich), // Er ist nicht reinlich.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wenn man der Jugend reine Wahrheit sagt, // Die gelben Schnäbeln keineswegs behagt, // Sie aber hintendrein nach Jahren // Das alles derb an eigner Haut erfahren, // Dann dünkeln sie, es käm aus eignem Schopf.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wenn sich lau die Lüfte füllen // Um den grün umschränkten Plan, // Süße Düfte, Nebelhüllen // Senkt die Dämmerung heran. // Lispelt leise süßen Frieden, // Wiegt das Herz in Kindesruh; // Und den Augen dieses Müden // Schließt des Tages Pforte zu.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer befehlen soll, // muss im Befehlen Seligkeit empfinden.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer immer strebend sich bemüht, // Den können wir erlösen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer kann was Dummheit, wer was Klugheit denken, // Das nicht die Vorwelt schon gedacht?", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wer lange lebt, hat viel erfahren, // Nichts Neues kann für ihn auf dieser Welt geschehn.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wie hässlich neben Schönheit zeigt sich Hässlichkeit.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wie sich Verdienst und Glück verketten, // Das fällt den Toren niemals ein; // Wenn sie den Stein der Weisen hätten, // Der Weise mangelte dem Stein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Wo fehlt's nicht irgendwo auf dieser Welt? // Dem dies, dem das, hier aber fehlt das Geld.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Zum Sehen geboren, // Zum Schauen bestellt.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Euch gibt es zwei Dinge // So herrlich und groß: // Das glänzende Gold // Und der weibliche Schoß. // Das eine verschaffet, // Das andre verschlingt; // Drum glücklich, wer beide // Zusammen erringt!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die meisten verarbeiten den größten Teil der Zeit, um zu leben, und das bisschen, das ihnen von Freiheit übrig bleibt, ängstigt sie so, dass sie alle Mittel aufsuchen, um es los zu werden.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Natur […] allein ist unendlich reich und sie allein bildet den großen Künstler.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Die Stadt selbst ist unangenehm, dagegen rings umher eine unaussprechliche Schönheit der Natur.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein Mensch, der um anderer willen, ohne dass es seine eigene Leidenschaft, sein eigenes Bedürfnis ist, sich um Geld oder Ehre oder sonst etwas abarbeitet, ist immer ein Tor.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ein leichter Sinn trägt alles!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Guter Gott von deinem Himmel, alte Kinder siehst du und junge Kinder, und nichts weiter; und an welchen du mehr Freude hast, das hat dein Sohn schon lange verkündet.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ich brauche Wiegengesang, und den habe ich in seiner Fülle gefunden in meinem Homer.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ich könnte jetzt nicht zeichnen und bin nie ein größerer Maler gewesen als in diesen Augenblicken.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Und ich habe […] gefunden, dass Missverständnisse und Trägheit vielleicht mehr Irrungen in der Welt machen als List und Bosheit. Wenigstens sind die beiden letzteren gewiß seltener.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Ach, was ich weiß, kann jeder wissen – mein Herz habe ich allein.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Alles Gescheite ist schon gedacht worden. Man muss nur versuchen, es noch einmal zu denken.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "An der Farbe lässt sich die Sinnesweise, an dem Schnitt die Lebensweise des Menschen erkennen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Aufmerksamkeit ist das Leben!", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Bekanntschaften, wenn sie sich auch gleichgültig ankündigen, haben oft die wichtigsten Folgen.", Author = "Johann Wolfgang von Goethe" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Wolfgang_von_Goethe", Text = "Das Allgemeine und Besondere fallen zusammen; das Besondere ist das Allgemeine, unter verschiedenen Bedingungen erscheinend.", Author = "Johann Wolfgang von Goethe" },
        };
    }
}
